using System.Text.RegularExpressions;
using ImageStore.Domain.Images;

namespace ImageStore.Application.Images.Storage;

/// <summary>
/// Builds and validates storage paths of the form <c>{ownerUserId}/{imageId}.{ext}</c>.
/// Both segments are GUIDs generated by the server, so a valid path can never contain
/// traversal sequences, separators in unexpected places, or client-supplied names.
/// </summary>
public static partial class ImageStoragePaths
{
    public static string CreateStoredFileName(Guid imageId, string extension)
    {
        if (imageId == Guid.Empty)
        {
            throw new ArgumentException("The image identifier is required.", nameof(imageId));
        }

        if (!ExtensionRegex().IsMatch(extension))
        {
            throw new ArgumentException("The extension must look like '.jpg'.", nameof(extension));
        }

        return string.Concat(imageId.ToString("D"), extension);
    }

    public static string CreateRelativePath(Guid ownerUserId, string storedFileName)
    {
        if (ownerUserId == Guid.Empty)
        {
            throw new ArgumentException("The owner identifier is required.", nameof(ownerUserId));
        }

        var path = $"{ownerUserId:D}/{storedFileName}";
        return IsValidRelativePath(path)
            ? path
            : throw new ArgumentException("The stored file name is not valid.", nameof(storedFileName));
    }

    /// <summary>Strict allow-list check used before every file-system access.</summary>
    public static bool IsValidRelativePath(string? relativePath) =>
        relativePath is not null
        && relativePath.Length <= ImageRules.RelativeStoragePathMaxLength
        && RelativePathRegex().IsMatch(relativePath);

    [GeneratedRegex(@"^\.[a-z0-9]{1,10}\z", RegexOptions.CultureInvariant)]
    private static partial Regex ExtensionRegex();

    [GeneratedRegex(
        @"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]{1,10}\z",
        RegexOptions.CultureInvariant)]
    private static partial Regex RelativePathRegex();
}
